// 1) the (start, end) clump -> a real concept. Good.
+class DateRange {
+  constructor(readonly start: Date, readonly end: Date) {
+    if (end < start) throw new RangeError('end before start');
+  }
+  get nights() { return Math.round((+this.end - +this.start) / 86_400_000); }
+}

// 2) but then, to shorten reserve(), everything is bagged together:
+type ReserveParams = {
+  range: DateRange; guestId: string; roomId: string;
+  notifyByEmail: boolean; promoCode?: string; sourceChannel: string;
+};
 function reserve(p: ReserveParams): Reservation { /* ... */ }

// 3) whole-object applied to a callee that needs ONE field:
-function isPeak(month: number): boolean { return month >= 5 && month <= 8; }
+function isPeak(range: DateRange): boolean {
+  const month = range.start.getMonth();
+  return month >= 5 && month <= 8;
+}
